import { IEnvironmentAware } from "../environment-aware";
import * as constructs from "constructs";
/**
 * Indicates that this resource can be referenced as a Outpost.
 *
 * @stability experimental
 */
export interface IOutpostRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Outpost resource.
     */
    readonly outpostRef: OutpostReference;
}
/**
 * A reference to a Outpost resource.
 *
 * @struct
 * @stability external
 */
export interface OutpostReference {
    /**
     * The OutpostArn of the Outpost resource.
     */
    readonly outpostArn: string;
}
/**
 * Indicates that this resource can be referenced as a Site.
 *
 * @stability experimental
 */
export interface ISiteRef extends constructs.IConstruct, IEnvironmentAware {
    /**
     * A reference to a Site resource.
     */
    readonly siteRef: SiteReference;
}
/**
 * A reference to a Site resource.
 *
 * @struct
 * @stability external
 */
export interface SiteReference {
    /**
     * The SiteArn of the Site resource.
     */
    readonly siteArn: string;
}
